            aWandererI = aWandererI ^ (((RotL64(aPrevious, 18U) + aOrbiterH) + RotL64(aOrbiterB, 3U)) + aWUSaltC[(((511U - aIndex) + 275U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aCross, 3U) + aOrbiterJ) + RotL64(aOrbiterH, 27U)) + RotL64(aCarry, 5U));
