            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0x5A9AED4B6DBA5D5AULL) + aNonceWordI;
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x93ED710B5FDDB302ULL;
