            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x05F86582C1719129ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x24CAB55E213BE7E7ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x24DDB03590E92421ULL), 53U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xABC1B23E1C56A5D7ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x56953D8D6D2F1337ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x4AAE778EF7A95563ULL), 19U);
